import Vue from 'vue';
import { Component, Prop } from 'vue-property-decorator';
import { INicknameState } from '../../types';

@Component({
})
export default class SubmitButton extends Vue {
    @Prop()
    protected translation: string;

    @Prop()
    protected state: INicknameState;

    get isActive(): boolean {
        return this.state.requirements.alphaNumeric && this.state.requirements.length && this.state.requirements.startingCharacter && !this.state.isSubmitting;
    }

    protected submitNickname(): void {
        if (this.isActive) {
            this.state.isSubmitting = true;
            this.$emit('submitNickname');
        }
    }
}
